import psycopg2
import os
from flask import Flask, request, jsonify, g
import hashlib
import time

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret123')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST,
            database=DB_NAME,
            user=DB_USER,
            password=DB_PASS
        )
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def log_access(user_id, action, detail):
    """Audit logging - writes to separate audit schema"""
    db = get_db()
    cur = db.cursor()
    cur.execute(
        "INSERT INTO audit.access_log (user_id, action, detail, ts) VALUES (%s, %s, %s, NOW())",
        (user_id, action, detail)
    )
    db.commit()
    cur.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports flexible filtering."""
    query_field = request.args.get('field', 'username')
    query_value = request.args.get('q', '')
    page = request.args.get('page', '1')

    # Basic field validation - only allow known columns
    allowed_fields = ['username', 'email', 'display_name', 'department', 'role']
    if query_field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    if not query_value:
        return jsonify({'error': 'Query parameter required'}), 400

    db = get_db()
    cur = db.cursor()

    # Field is validated above, but value is interpolated for LIKE pattern support
    # The field name is safe (from allowlist), so we build the query dynamically
    sql = f"SELECT id, username, email, display_name, department FROM users WHERE {query_field} LIKE '%{query_value}%' ORDER BY username LIMIT 20 OFFSET {(int(page)-1)*20}"

    try:
        cur.execute(sql)
        rows = cur.fetchall()
        results = []
        for row in rows:
            results.append({
                'id': row[0],
                'username': row[1],
                'email': row[2],
                'display_name': row[3],
                'department': row[4]
            })

        log_access('anonymous', 'search', f"{query_field}={query_value}")
        return jsonify({'results': results, 'count': len(results)})
    except Exception as e:
        db.rollback()
        return jsonify({'error': 'Search failed'}), 500
    finally:
        cur.close()

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    cur = db.cursor()
    cur.execute("SELECT id, username, email, display_name, department, role FROM users WHERE id = %s", (user_id,))
    row = cur.fetchone()
    cur.close()
    if row:
        return jsonify({'id': row[0], 'username': row[1], 'email': row[2], 'display_name': row[3], 'department': row[4], 'role': row[5]})
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/health', methods=['GET'])
def health():
    try:
        db = get_db()
        cur = db.cursor()
        cur.execute("SELECT 1")
        cur.close()
        return jsonify({'status': 'healthy', 'db': 'connected'})
    except:
        return jsonify({'status': 'unhealthy', 'db': 'disconnected'}), 503

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
